#pragma once

/**
 * Short pre-rendered spoken status cues (PCM16 mono @ 24 kHz, marin voice).
 * Data lives in status_cues_data.cpp (generated by tools/gen_status_cues.py).
 * play() enqueues into audio_out; call audio_out::waitDrained() when the cue
 * must finish before the next sound or before the mic resumes.
 */
namespace status_cues
{

enum class Cue
{
    WifiConnected,
    YouCanSpeakNow,
};

/** Non-blocking: copies the clip into the playback ring. */
void play(Cue cue);

} // namespace status_cues
